sp_widget.client_script:
function widgetcontroller($scope, $timeout, $rootScope, $document, $window) {
  var c = this;
  c.loading = false;
  c.tableSearch = '';
  c.filteredList = [];
  c.limit = 15;
  c.page = 0;

  // Cached Counts for HTML
  c.counts = { total: 0, overdue: 0, review15: 0, review30: 0, highRisk: 0, highGrowth: 0, pending: 0, sendBack: 0, rejected: 0, expiring: 0 };

  // Filters – business added
  c.filters = {
    business: 'T00',   // default Trade
    segments: [],
    zones: [],
    regions: [],
    depot: '',
    period: 'latest'
  };

  function handleClickOutside(event) {
    var target = event.target;
    if (target.closest('.clm-multiselect-container') || target.closest('.clm-custom-dropdown')) return;
    $timeout(function() {
      c.segmentDropdownOpen = false;
      c.zoneDropdownOpen = false;
      c.regionDropdownOpen = false;
      c.dropdownOpen.depot = false;
    });
  }
  $document.on('click', handleClickOutside);
  $scope.$on('$destroy', function() { $document.off('click', handleClickOutside); });

  /* ===================== SEGMENT ===================== */
  c.segmentDropdownOpen = false;
  c.segmentSearch = '';
  c.selectedSegmentLabels = [];
  c.openSegmentDropdown = function() { c.segmentDropdownOpen = true; c.zoneDropdownOpen = false; c.regionDropdownOpen = false; c.dropdownOpen.depot = false; };
  c.closeSegmentDropdown = function() { $timeout(function() { c.segmentDropdownOpen = false; }, 200); };
  function cascadeResetBelowSegment() {
      c.filters.zones = []; c.selectedZoneLabels = []; c.filters.regions = []; c.selectedRegionLabels = [];
      c.filters.depot = ''; c.zoneSearch = ''; c.regionSearch = '';
  }
  c.toggleSegment = function(s) {
      var idx = c.filters.segments.indexOf(s.value);
      if (idx === -1) { c.filters.segments.push(s.value); c.selectedSegmentLabels.push(s.label); } 
      else { c.filters.segments.splice(idx, 1); c.selectedSegmentLabels.splice(idx, 1); }
      cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh();
  };
  c.selectAllSegments = function() {
      var allSegments = (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
      c.filters.segments = allSegments.map(function(s) { return s.value; });
      c.selectedSegmentLabels = allSegments.map(function(s) { return s.label; });
      cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh();
  };
  c.clearAllSegments = function() { c.filters.segments = []; c.selectedSegmentLabels = []; cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh(); };
  c.isSegmentSelected = function(s) { return c.filters.segments.indexOf(s.value) !== -1; };
  c.getFilteredSegments = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
      var term = (c.segmentSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(s) { return String(s.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getSegmentDisplayText = function() {
      if (!c.selectedSegmentLabels || c.selectedSegmentLabels.length === 0) return 'All Segments';
      if (c.selectedSegmentLabels.length === 1) return c.selectedSegmentLabels[0];
      return c.selectedSegmentLabels.length + ' segments selected';
  };

  /* ===================== ZONE ===================== */
  c.zoneDropdownOpen = false;
  c.zoneSearch = '';
  c.selectedZoneLabels = [];
  c.openZoneDropdown = function() { c.zoneDropdownOpen = true; c.segmentDropdownOpen = false; c.regionDropdownOpen = false; c.dropdownOpen.depot = false; };
  c.closeZoneDropdown = function() { $timeout(function() { c.zoneDropdownOpen = false; }, 200); };
  c.toggleZone = function(z) {
      var idx = c.filters.zones.indexOf(z.value);
      if (idx === -1) { c.filters.zones.push(z.value); c.selectedZoneLabels.push(z.label); } 
      else { c.filters.zones.splice(idx, 1); c.selectedZoneLabels.splice(idx, 1); }
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depot = '';
      c.zoneSearch = ''; c.refresh();
  };
  c.selectAllZones = function() {
      var allZones = (c.data && c.data.filterOpts && c.data.filterOpts.zones) || [];
      c.filters.zones = allZones.map(function(z) { return z.value; });
      c.selectedZoneLabels = allZones.map(function(z) { return z.label; });
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depot = '';
      c.zoneSearch = ''; c.refresh();
  };
  c.clearAllZones = function() {
      c.filters.zones = []; c.selectedZoneLabels = []; c.filters.regions = []; c.selectedRegionLabels = [];
      c.filters.depot = ''; c.zoneSearch = ''; c.refresh();
  };
  c.isZoneSelected = function(z) { return c.filters.zones.indexOf(z.value) !== -1; };
  c.getFilteredZones = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.zones) || [];
      var term = (c.zoneSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(z) { return String(z.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getZoneDisplayText = function() {
      if (!c.selectedZoneLabels || c.selectedZoneLabels.length === 0) return 'All Zones';
      if (c.selectedZoneLabels.length === 1) return c.selectedZoneLabels[0];
      return c.selectedZoneLabels.length + ' zones selected';
  };

  /* ===================== REGION ===================== */
  c.regionDropdownOpen = false;
  c.regionSearch = '';
  c.selectedRegionLabels = [];
  c.openRegionDropdown = function() { c.regionDropdownOpen = true; c.segmentDropdownOpen = false; c.zoneDropdownOpen = false; c.dropdownOpen.depot = false; };
  c.closeRegionDropdown = function() { $timeout(function() { c.regionDropdownOpen = false; }, 200); };
  c.toggleRegion = function(r) {
      var idx = c.filters.regions.indexOf(r.value);
      if (idx === -1) { c.filters.regions.push(r.value); c.selectedRegionLabels.push(r.label); } 
      else { c.filters.regions.splice(idx, 1); c.selectedRegionLabels.splice(idx, 1); }
      c.filters.depot = ''; c.regionSearch = ''; c.refresh();
  };
  c.selectAllRegions = function() {
      var allRegions = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      c.filters.regions = allRegions.map(function(r) { return r.value; });
      c.selectedRegionLabels = allRegions.map(function(r) { return r.label; });
      c.filters.depot = ''; c.regionSearch = ''; c.refresh();
  };
  c.clearAllRegions = function() {
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depot = '';
      c.regionSearch = ''; c.refresh();
  };
  c.isRegionSelected = function(r) { return c.filters.regions.indexOf(r.value) !== -1; };
  c.getFilteredRegions = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      var term = (c.regionSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(r) { return String(r.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getRegionDisplayText = function() {
      if (!c.selectedRegionLabels || c.selectedRegionLabels.length === 0) return 'All Regions';
      if (c.selectedRegionLabels.length === 1) return c.selectedRegionLabels[0];
      return c.selectedRegionLabels.length + ' regions selected';
  };

  /* ===================== DEPOT CUSTOM DROPDOWN ===================== */
  c.dropdownOpen = { depot: false };
  var OPTS_MAP = { depot: 'depots' };
  c.openDropdown = function(f) {
      c.dropdownOpen[f] = true;
      if (f === 'depot') {
          c.zoneDropdownOpen = false;
          c.regionDropdownOpen = false;
          c.segmentDropdownOpen = false;
      }
  };
  c.closeDropdown = function(f) { $timeout(function() { c.dropdownOpen[f] = false; }, 150); };
  c.onFilterInput = function(f) { c.dropdownOpen[f] = true; c.refresh(); };
  c.getFilteredOptions = function(f) {
      var all = c.data.filterOpts[OPTS_MAP[f]] || [];
      var term = (c.filters[f] || '').toLowerCase();
      return term ? all.filter(function(o) { return String(o.label || o).toLowerCase().indexOf(term) !== -1; }) : all;
  };
  c.selectOption = function(f, v) { c.filters[f] = v.value; c.dropdownOpen[f] = false; c.refresh(); };
  c.clearFilter = function(f, $event) {
      if ($event) $event.preventDefault();
      c.filters[f] = '';
      c.refresh();
  };

  /* ===================== QUICK FILTERS & SORTING ===================== */
  c.quickFilter = 'all';
  c.riskFilter = '';
  c.kpiFilter = '';
  c.largeExposureSortOrder = 'desc';

  c.setQuickFilter = function(f) { c.quickFilter = f; c.page = 0; if (f === 'largeExposure') { c._top20Codes = null; c.largeExposureSortOrder = 'desc'; } c.applyLocalFilters(); };
  c.setKpiFilter = function(filterName) {
      c.kpiFilter = (c.kpiFilter === filterName) ? '' : filterName;
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() { var el = document.getElementById('clmTableContainer'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 100);
  };
  c.setRiskKpiFilter = function() {
      c.riskFilter = (c.riskFilter === 'High') ? '' : 'High';
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() { var el = document.getElementById('clmTableContainer'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 100);
  };

  c.toggleLargeExposureSort = function() {
      c.largeExposureSortOrder = c.largeExposureSortOrder === 'desc' ? 'asc' : 'desc';
      c._top20Codes = null; c.lastCacheBuster++;
      if (c.quickFilter === 'largeExposure') { c.page = 0; c.applyLocalFilters(); }
  };
  c.getLargeExposureIcon = function() { return c.largeExposureSortOrder === 'desc' ? 'fa-sort-amount-desc' : 'fa-sort-amount-asc'; };

  c.isOverdue = function(row) {
      var val = row.overdueBalance !== undefined ? row.overdueBalance : (row.overdue !== undefined ? row.overdue : row.od90);
      return !!val && Number(val) > 0;
  };
  c.getReviewDays = function(row) {
      if (row.reviewDays !== undefined && row.reviewDays !== null) return Number(row.reviewDays);
      var parsed = parseInt(row.reviewIn, 10);
      return isNaN(parsed) ? null : parsed;
  };
  c.isReviewWithin = function(row, days) { var d = c.getReviewDays(row); return d !== null && d >= 0 && d <= days; };
  c.isHighRisk = function(row) { return row.risk === 'High'; };

  // ===================== SEGMENT / ZONE / REGION RISK HEATMAP =====================
  c.heatState = { segment: '', zone: '' };
  c.selectedHeatRegion = null;
  c.riskMatrixLevel = 'segment';
  c.riskMatrixData = [];
  c.riskMatrixMax = 0;

  c.buildRiskMatrix = function() {
      var rows = (c.data && c.data.tableData) || [];
      var level, keyFn;

      if (!c.heatState.segment) {
          level = 'segment';
          keyFn = function(r) { return r.segment; };
      } else if (!c.heatState.zone) {
          level = 'zone';
          rows = rows.filter(function(r) { return r.segment === c.heatState.segment; });
          keyFn = function(r) { return r.zoneName || r.zone; };
      } else {
          level = 'region';
          rows = rows.filter(function(r) { return r.segment === c.heatState.segment && (r.zoneName === c.heatState.zone || r.zone === c.heatState.zone); });
          keyFn = function(r) { return r.regionName || r.region; };
      }

      var map = {};
      rows.forEach(function(row) {
          var key = keyFn(row) || '(Unassigned)';
          if (!map[key]) { map[key] = { label: key, totalOutstanding: 0, totalOd90: 0, customerCount: 0, highRiskCount: 0, mediumRiskCount: 0, lowRiskCount: 0 }; }
          map[key].totalOutstanding += row.outstanding || 0;
          map[key].totalOd90 += row.od90 || 0;
          map[key].customerCount++;
          if (row.risk === 'High') map[key].highRiskCount++;
          else if (row.risk === 'Medium') map[key].mediumRiskCount++;
          else if (row.risk === 'Low') map[key].lowRiskCount++;
      });
      c.riskMatrixLevel = level;
      c.riskMatrixData = Object.keys(map).map(function(k) { return map[k]; }).sort(function(a, b) { return b.totalOd90 - a.totalOd90; });
      c.riskMatrixMax = c.riskMatrixData.length > 0 ? c.riskMatrixData[0].totalOd90 : 1;
  };

  c.drillMatrix = function(item) {
      if (c.riskMatrixLevel === 'segment') { 
          c.heatState.segment = item.label; 
          c.page = 0;
          c.applyLocalFilters();
      } else if (c.riskMatrixLevel === 'zone') { 
          c.heatState.zone = item.label; 
          c.page = 0;
          c.applyLocalFilters();
      } else {
          if (c.selectedHeatRegion === item.label) { c.selectedHeatRegion = null; } 
          else { c.selectedHeatRegion = item.label; }
          c.page = 0;
          c.applyLocalFilters();
          $timeout(function() { var el = document.getElementById('clmTableContainer'); if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }, 50);
          return;
      }
      c.buildRiskMatrix();
  };

  c.resetHeatToSegments = function() { 
      c.heatState.segment = ''; c.heatState.zone = ''; c.selectedHeatRegion = null; 
      c.page = 0; c.applyLocalFilters(); c.buildRiskMatrix(); 
  };
  c.resetHeatToZones = function() { 
      c.heatState.zone = ''; c.selectedHeatRegion = null; 
      c.page = 0; c.applyLocalFilters(); c.buildRiskMatrix(); 
  };
  c.clearHeatDrilldown = function() { 
      c.heatState.segment = ''; c.heatState.zone = ''; c.selectedHeatRegion = null; c.riskMatrixLevel = 'segment';
      c.page = 0; c.applyLocalFilters(); c.buildRiskMatrix(); 
  };

  var HEAT_RED = '#e53e3e'; var HEAT_ORANGE = '#f6ad55'; var HEAT_YELLOW = '#f6e05e'; var HEAT_GREEN = '#c6f6d5';

  c.getHeatColor = function(item) {
      var highCount = (item && item.highRiskCount) || 0;
      if (highCount >= 100) return HEAT_RED;
      if (highCount >= 10) return HEAT_ORANGE;
      if (highCount >= 1) return HEAT_YELLOW;
      return HEAT_GREEN;
  };

  c.getHeatTextColor = function(item) { 
      var color = c.getHeatColor(item); 
      return (color === HEAT_RED || color === HEAT_ORANGE) ? '#fff' : '#1f2933'; 
  };

  c.regionTooltip = { show: false, x: 0, y: 0, data: null };
  c.showRegionTooltip = function(event, item) {
      c.regionTooltip.data = item;
      var container = event.currentTarget.closest('.clm-heatmap-container');
      if (!container) return;
      var containerRect = container.getBoundingClientRect();
      var targetRect = event.currentTarget.getBoundingClientRect();
      var left = targetRect.right - containerRect.left + 14;
      var top = targetRect.top - containerRect.top;
      if (left + 220 > containerRect.width) { left = targetRect.left - containerRect.left - 220; }
      if (top + 140 > containerRect.height) { top = targetRect.bottom - containerRect.top - 140; }
      c.regionTooltip.x = left; c.regionTooltip.y = top; c.regionTooltip.show = true;
      $scope.$applyAsync();
  };
  c.hideRegionTooltip = function() { c.regionTooltip.show = false; $scope.$applyAsync(); };

  // ===================== FAST LOCAL FILTERING =====================
  c.getFilteredBaseData = function() {
      if (!c.data || !c.data.tableData) return [];
      var rows = c.data.tableData;
      if (c.selectedHeatRegion) {
          return rows.filter(function(r) { return r.region === c.selectedHeatRegion || r.regionName === c.selectedHeatRegion; });
      } else if (c.heatState.zone) {
          return rows.filter(function(r) { return r.segment === c.heatState.segment && (r.zone === c.heatState.zone || r.zoneName === c.heatState.zone); });
      } else if (c.heatState.segment) {
          return rows.filter(function(r) { return r.segment === c.heatState.segment; });
      }
      return rows;
  };

  c.getBaseTableCount = function() { return c.getFilteredBaseData().length; };
  c.countOverdue = function() { return c.getFilteredBaseData().filter(c.isOverdue).length; };
  c.countReview = function(days) { return c.getFilteredBaseData().filter(function(row) { return c.isReviewWithin(row, days); }).length; };
  c.countHighRisk = function() { return c.getFilteredBaseData().filter(c.isHighRisk).length; };

  c.getTop20Outstanding = function() {
      var filtered = c.getFilteredBaseData().filter(function(row) {
          if (c.kpiFilter) {
              var statLower = (row.status || '').toLowerCase();
              if (c.kpiFilter === 'Pending' && statLower.indexOf('pend') === -1) return false;
              if (c.kpiFilter === 'Send-back' && statLower.indexOf('send') === -1 && statLower.indexOf('back') === -1) return false;
              if (c.kpiFilter === 'Rejected' && statLower.indexOf('reject') === -1) return false;
          }
          if (c.riskFilter && row.risk !== c.riskFilter) return false;
          if (c.quickFilter !== 'largeExposure') {
              switch (c.quickFilter) {
                  case 'overdue':   if (!c.isOverdue(row)) return false; break;
                  case 'review15':  if (!c.isReviewWithin(row, 15)) return false; break;
                  case 'review30':  if (!c.isReviewWithin(row, 30)) return false; break;
              }
          }
          return true;
      });
      var sorted = filtered.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
      return sorted.slice(0, 20);
  };

  c.isTop20Customer = function(row) {
      if (!c._top20Codes || c._top20CacheBuster !== c.lastCacheBuster) {
          c._top20Codes = {};
          var top20 = c.getTop20Outstanding();
          top20.forEach(function(r) { c._top20Codes[r.code] = true; });
          c._top20CacheBuster = c.lastCacheBuster;
      }
      return !!c._top20Codes[row.code];
  };
  c.lastCacheBuster = 0;

  c.applyLocalFilters = function() {
      updateCounts();

      var rows = c.getFilteredBaseData();

      if (c.kpiFilter) {
          rows = rows.filter(function(row) {
              var s = (row.status || '').toLowerCase();
              if (c.kpiFilter === 'Pending' && s.indexOf('pend') === -1) return false;
              if (c.kpiFilter === 'Send-back' && s.indexOf('send') === -1 && s.indexOf('back') === -1) return false;
              if (c.kpiFilter === 'Rejected' && s.indexOf('reject') === -1) return false;
              return true;
          });
      }

      if (c.riskFilter) {
          rows = rows.filter(function(row) { return row.risk === c.riskFilter; });
      }

      var q = (c.tableSearch || '').toLowerCase().trim();
      if (q) {
          rows = rows.filter(function(row) {
              return (row.code || '').toLowerCase().indexOf(q) > -1 ||
                     (row.name || '').toLowerCase().indexOf(q) > -1 ||
                     (row.pan  || '').toLowerCase().indexOf(q) > -1 ||
                     (row.region || '').toLowerCase().indexOf(q) > -1 ||
                     (row.regionName || '').toLowerCase().indexOf(q) > -1 ||
                     (row.depot  || '').toLowerCase().indexOf(q) > -1 ||
                     (row.zoneName || '').toLowerCase().indexOf(q) > -1;
          });
      }

      if (c.quickFilter === 'largeExposure') {
          rows = rows.filter(function(row) { return (row.od90 || 0) > 0; });
          rows.sort(function(a, b) {
              var diff = (b.od90 || 0) - (a.od90 || 0);
              return c.largeExposureSortOrder === 'desc' ? diff : -diff;
          });
          rows = rows.slice(0, 20);
      } else if (c.quickFilter === 'highGrowth20') {
          rows = rows.filter(function(row) { return row.highGrowth20 === 'Yes'; });
          rows.sort(function(a, b) { return (b.avgMonthlySales || 0) - (a.avgMonthlySales || 0); });
          rows = rows.slice(0, 20);
      } else {
          if (c.quickFilter === 'overdue') rows = rows.filter(c.isOverdue);
          else if (c.quickFilter === 'review15') rows = rows.filter(function(row) { return c.isReviewWithin(row, 15); });
          else if (c.quickFilter === 'review30') rows = rows.filter(function(row) { return c.isReviewWithin(row, 30); });

          rows.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
      }

      c.filteredList = rows;
      c.updatePagination();
  };

  function updateCounts() {
      var base = c.getFilteredBaseData();
      c.counts.total = base.length;
      c.counts.overdue = 0; c.counts.review15 = 0; c.counts.review30 = 0; 
      c.counts.highRisk = 0; c.counts.highGrowth = 0;
      c.counts.pending = 0; c.counts.sendBack = 0; c.counts.rejected = 0; c.counts.expiring = 0;

      for (var i = 0; i < base.length; i++) {
          var r = base[i];
          if (c.isOverdue(r)) c.counts.overdue++;
          if (c.isReviewWithin(r, 15)) c.counts.review15++;
          if (c.isReviewWithin(r, 30)) c.counts.review30++;
          if (r.risk === 'High') c.counts.highRisk++;
          if (r.highGrowth20 === 'Yes') c.counts.highGrowth++;
          if (r.status === 'Pending') c.counts.pending++;
          if (r.status === 'Send-back') c.counts.sendBack++;
          if (r.status === 'Rejected') c.counts.rejected++;
          if (r.reviewIn && parseInt(r.reviewIn) <= 15) c.counts.expiring++;
      }
  }

  c.getActiveFilterCount = function() {
      var cnt = 0;
      if (c.filters.zones.length > 0) cnt++;
      if (c.filters.regions.length > 0) cnt++;
      if (c.filters.depot) cnt++;
      if (c.filters.segments.length > 0) cnt++;
      if (c.filters.period && c.filters.period !== 'latest') cnt++;
      if (c.riskFilter) cnt++;
      if (c.kpiFilter) cnt++;
      if (c.quickFilter !== 'all') cnt++;
      if (c.heatState.segment || c.selectedHeatRegion) cnt++;
      return cnt;
  };

  c.clearAllFilters = function() {
      c.filterWrapperClass = 'collapsing';
      $timeout(function() {
          c.filters.zones = []; c.selectedZoneLabels = [];
          c.filters.regions = []; c.selectedRegionLabels = [];
          c.filters.depot = ''; c.filters.segments = []; c.selectedSegmentLabels = [];
          c.filters.period = 'latest';
          c.riskFilter = ''; c.kpiFilter = ''; c.quickFilter = 'all';
          c.tableSearch = ''; 
          c.heatState = { segment: '', zone: '' }; 
          c.selectedHeatRegion = null; 
          c.riskMatrixLevel = 'segment';
          c.page = 0; c._top20Codes = null; c.lastCacheBuster++;
          c.filterWrapperClass = ''; c.refresh();
      }, 350);
  };

  c.onPeriodChange = function() {
      if (!allTimeTableData.length) return;
      var filtered = filterRowsByPeriod(allTimeTableData, c.filters.period);
      c.data.tableData = filtered;
      c.data.kpis = recalcKpisFromRows(filtered);
      c.buildRiskMatrix();
      c.applyLocalFilters();
  };

  var allTimeTableData = [];
  function getPeriodBounds(period) {
      var now = new Date();
      var start = null, end = new Date();
      if (period === 'this_month') { start = new Date(now.getFullYear(), now.getMonth(), 1); } 
      else if (period === 'last_month') { start = new Date(now.getFullYear(), now.getMonth() - 1, 1); end = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59); } 
      else if (period === 'this_year') { start = new Date(now.getFullYear(), 0, 1); } 
      else if (period === 'last_year') { start = new Date(now.getFullYear() - 1, 0, 1); end = new Date(now.getFullYear() - 1, 11, 31, 23, 59, 59); }
      return { start: start, end: end };
  }

  function filterRowsByPeriod(rows, period) {
      if (period === 'latest') return rows;
      var bounds = getPeriodBounds(period);
      if (!bounds.start) return rows;
      return rows.filter(function(row) {
          var d = row.createdOn;
          if (!d) return false;
          var rd = new Date(d.substring(0,10));
          return rd >= bounds.start && rd <= bounds.end;
      });
  }

  function recalcKpisFromRows(rows) {
      var count = rows.length;
      var limit = 0, outstanding = 0, available = 0, utilPct = 0;
      var overdueExp = 0, od90 = 0, grossExp = 0;
      var totalActiveSd = 0, totalOsSales = 0;

      rows.forEach(function(r) {
          limit += (r.limit || 0); 
          outstanding += (r.outstanding || 0);
          overdueExp += (r.overdueTotal || 0);
          od90 += (r.od90 || 0);
          grossExp += (r.grossExp || 0);
          totalActiveSd += (r.activeSd || 0);
          totalOsSales += (r.osSalesRatio || 0);
      });

      available = limit - outstanding;
      utilPct = limit > 0 ? Math.round((outstanding / limit) * 100) : 0;

      var hhiSum = 0;
      if (outstanding > 0) {
          rows.forEach(function(r) {
              var share = (r.outstanding || 0) / outstanding * 100;
              hhiSum += share * share;
          });
      }
      var concentrationRisk = Math.round(hhiSum);
      var concentrationLabel = 'Less';
      if (concentrationRisk > 2500) concentrationLabel = 'High';
      else if (concentrationRisk >= 1500) concentrationLabel = 'Moderate';

      var netExposure = outstanding - totalActiveSd;

      return {
          customerCount: count, limit: limit, outstanding: outstanding, available: available, utilPct: utilPct,
          overdueExposure: overdueExp, od90: od90, grossExposure: grossExp,
          concentrationRisk: concentrationRisk, concentrationLabel: concentrationLabel,
          netExposure: netExposure, osSalesRatioSum: totalOsSales
      };
  }

  // Business change triggers full refresh
  c.onBusinessChange = function() {
      c.refresh();
  };

  c.refresh = function() {
      c.loading = true;
      c.page = 0;
      c._top20Codes = null;
      c.lastCacheBuster++;
      var payload = { filters: angular.copy(c.filters) };
      if (c.data && c.data.filterOpts) {
          if (payload.filters.zones && payload.filters.zones.length === (c.data.filterOpts.zones || []).length) {
              payload.filters.zones = [];
          }
          if (payload.filters.regions && payload.filters.regions.length === (c.data.filterOpts.regions || []).length) {
              payload.filters.regions = [];
          }
      }

      c.server.get(payload).then(function(r) {
          c.data = r.data;
          allTimeTableData = c.data.tableData || [];
          if (Array.isArray(allTimeTableData)) {
              allTimeTableData.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
          }
          c.data.tableData = filterRowsByPeriod(allTimeTableData, c.filters.period);
          c.data.kpis = recalcKpisFromRows(c.data.tableData);

          c.largeExposureSortOrder = 'desc';
          c._top20Codes = null;
          c.lastCacheBuster++;
          c.buildRiskMatrix();
          c.buildTrendChart();
          c.renderCharts();
          c.applyLocalFilters();
          $timeout(function(){ c.loading = false; }, 200);
      }).catch(function(error) {
          console.error('CCH Portfolio widget server error:', error);
          c.loading = false;
      });
  };

  c.updatePagination = function() { c.page = 0; };
  c.getPageArray = function() {
      if (!c.filteredList) return [0];
      var totalPages = Math.ceil(c.filteredList.length / c.limit);
      if (totalPages === 0) return [0];
      var maxPage = totalPages - 1;
      var start = Math.max(0, c.page - 2);
      var end = Math.min(maxPage, c.page + 2);
      var arr = [];
      for (var i = start; i <= end; i++) { arr.push(i); }
      return arr;
  };

  c.fmtCurrency = function(value) {
      if (value === undefined || value === null || isNaN(value)) return '—';
      var abs = Math.abs(value);
      var sign = value < 0 ? '-' : '';
      if (abs === 0) return '₹0.0L';
      if (abs >= 1e7) return sign + '₹' + (abs / 1e7).toFixed(1) + ' Cr';
      return sign + '₹' + (abs / 1e5).toFixed(1) + 'L';
  };

  c.fmtDash = function(val) { if (!val || isNaN(val) || val === 0) return '—'; return c.fmtCurrency(val); };
  c.fmtRatio = function(value) { if (value === undefined || value === null || isNaN(value)) return '—'; return Number(value).toFixed(2); };
  c.capPct = function(pct) { if (pct === undefined || pct === null || isNaN(pct)) return 0; return Math.max(0, Math.min(100, pct)); };

  c.selectCustomer = function(row) {
      if (!row || !row.sysId) return;
      $rootScope.clmPendingCustomerSysId = row.sysId || null;
      $rootScope.clmPendingCustomerCode = row.code;
      $rootScope.$broadcast('clm.customer.selected', { sysId: row.sysId || null, code: row.code });
      $rootScope.$broadcast('clm.switch.tab', 'customer360');
  };

  // ===================== CHART 1: Total Outstanding MoM Trend (SVG) =====================
  c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };

  c.buildTrendChart = function() {
      var trend = (c.data && c.data.trend && c.data.trend.points) || [];
      if (!trend.length) {
          c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };
          return;
      }
      var width = 1200, height = 260, padLeft = 90, padRight = 60, padY = 25, padBottom = 35;
      var drawHeight = height - padY - padBottom;
      var baselineY = padY + drawHeight;
      var values = trend.map(function(p) { return p.value || 0; });
      var maxVal = Math.max.apply(null, values.concat([0]));
      var minVal = 0;
      if (maxVal <= 0) { maxVal = 1; }
      maxVal = maxVal * 1.1;
      var n = trend.length;
      var stepX = (width - padLeft - padRight) / (n > 1 ? (n - 1) : 1);
      var pts = trend.map(function(p, i) {
          var plotValue = Math.max(0, p.value || 0);
          var x = padLeft + i * stepX;
          var y = padY + (1 - (plotValue - minVal) / (maxVal - minVal)) * drawHeight;
          return { x: x, y: y, label: p.label, value: p.value || 0 };
      });
      var activePts = pts.slice();
      var yTicks = [];
      var tickCount = 4;
      for (var j = 0; j < tickCount; j++) {
          var tickVal = minVal + (maxVal - minVal) * (j / (tickCount - 1));
          var tickY = padY + (1 - (tickVal - minVal) / (maxVal - minVal)) * drawHeight;
          yTicks.push({ y: tickY, label: c.fmtCurrency(tickVal) });
      }
      var linePoints = activePts.map(function(p) { return p.x + ',' + p.y; }).join(' ');
      var areaPath = 'M ' + activePts[0].x + ',' + baselineY + ' ';
      activePts.forEach(function(p) { areaPath += 'L ' + p.x + ',' + p.y + ' '; });
      areaPath += 'L ' + activePts[activePts.length - 1].x + ',' + baselineY + ' Z';
      c.trendChart = {
          points: pts, activePoints: activePts, yTicks: yTicks, linePoints: linePoints, areaPath: areaPath,
          width: width, height: height, padLeft: padLeft, padRight: padRight, padY: padY, drawHeight: drawHeight, baselineY: baselineY
      };
  };

  /* ===================== CHART.JS SETUP (v2.9.4) ===================== */
  var CHART_JS_URL = 'https://cdn.jsdelivr.net/npm/chart.js@2.9.4/dist/Chart.min.js'; 

  function ensureChartJs(cb) {
      if (typeof Chart !== 'undefined') { cb(); return; }
      if (!window.__clmChartJsPromise) {
          window.__clmChartJsPromise = new Promise(function(resolve, reject) {
              var existing = document.querySelector('script[data-clm-chartjs]');
              if (existing) {
                  existing.addEventListener('load', resolve);
                  existing.addEventListener('error', reject);
                  return;
              }
              var script = document.createElement('script');
              script.src = CHART_JS_URL;
              script.setAttribute('data-clm-chartjs', 'true');
              script.onload = resolve;
              script.onerror = reject;
              document.head.appendChild(script);
          });
      }
      window.__clmChartJsPromise.then(function() { $timeout(cb); }).catch(function(err) { console.error('CLM Widget: failed to load Chart.js', err); });
  }

  window.__clmChartVisibilityTargets = window.__clmChartVisibilityTargets || [];
  function isElementVisible(el) {
      if (!el || !document.body.contains(el)) return false;
      var rect = el.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
  }
  function ensureChartVisibilityWatcher() {
      if (window.__clmChartVisibilityWatcher) return;
      window.__clmChartVisibilityWatcher = new MutationObserver(function() {
          window.__clmChartVisibilityTargets.forEach(function(target) {
              var nowVisible = isElementVisible(target.canvas);
              if (nowVisible && !target.wasVisible) {
                  var inst = target.getInstance();
                  if (inst) { inst.resize(); }
              }
              target.wasVisible = nowVisible;
          });
      });
      window.__clmChartVisibilityWatcher.observe(document.body, { attributes: true, subtree: true, attributeFilter: ['class', 'style'] });
  }
  function registerChartVisibilityTarget(canvas, getChartInstance) {
      if (!canvas) return;
      var already = window.__clmChartVisibilityTargets.some(function(t) { return t.canvas === canvas; });
      if (!already) {
          window.__clmChartVisibilityTargets.push({ canvas: canvas, getInstance: getChartInstance, wasVisible: isElementVisible(canvas) });
      }
      ensureChartVisibilityWatcher();
  }

  // Dynamic ageing colors based on business
  c.getAgeingColors = function() {
      if (c.filters.business === 'N01') {
          return [
              { key: '0-30 Days',   color: '#38a169' },
              { key: '31-60 Days',  color: '#f6e05e' },
              { key: '61-90 Days',  color: '#f6ad55' },
              { key: '>90 Days',    color: '#e53e3e' }
          ];
      }
      // Default trade
      return [
          { key: '0-30 Days',    color: '#38a169' },
          { key: '31-60 Days',   color: '#f6e05e' },
          { key: '61-90 Days',   color: '#f6ad55' },
          { key: '91-120 Days',  color: '#ed7d31' },
          { key: '121-180 Days', color: '#dd6b20' },
          { key: '>180 Days',    color: '#e53e3e' }
      ];
  };

  var salesChartInstance = null;
  var ageingChartInstance = null;
  c.ageingLegend = [];

  c.renderCharts = function() {
    ensureChartJs(function() { renderSalesChart(); renderAgeingChart(); });
  };

  function renderSalesChart() {
      var canvas = document.getElementById('portfolioSalesChart');
      if (!canvas || !c.data.salesTrend || !c.data.salesTrend.points || !c.data.salesTrend.points.length) return;
      var labels = c.data.salesTrend.points.map(function(p) { return p.label || ''; });
      var volumes = c.data.salesTrend.points.map(function(p) { return p.volume || 0; });
      var values  = c.data.salesTrend.points.map(function(p) { return p.value || 0; });
      if (salesChartInstance) { try { salesChartInstance.destroy(); } catch(e) {} }
      salesChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar',
          data: {
              labels: labels,
              datasets: [
                  { type: 'line', label: 'Credit Sales Value (₹)', data: values, borderColor: '#ed7d31', backgroundColor: '#ed7d31', pointBackgroundColor: '#fff', pointBorderColor: '#ed7d31', pointBorderWidth: 2, pointRadius: 5, borderWidth: 3, lineTension: 0, fill: false, spanGaps: false, yAxisID: 'yValue' },
                  { type: 'bar', label: 'Credit Sales Volume (MT)', data: volumes, backgroundColor: '#4472c4', yAxisID: 'yVolume' }
              ]
          },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [
                      { id: 'yVolume', type: 'linear', position: 'left', scaleLabel: { display: true, labelString: 'Credit Sales Volume (MT)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } },
                      { id: 'yValue', type: 'linear', position: 'right', scaleLabel: { display: true, labelString: 'Credit Sales Value (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { drawOnChartArea: false } }
                  ]
              }
          }
      });
      registerChartVisibilityTarget(canvas, function() { return salesChartInstance; });
  }

  function renderAgeingChart() {
      var canvas = document.getElementById('portfolioAgeingChart');
      if (!canvas || !c.data.ageingTrend || !c.data.ageingTrend.months || !c.data.ageingTrend.months.length) return;
      var months = c.data.ageingTrend.months;
      var labels = months.map(function(m) { return m.label || ''; });

      var colours = c.getAgeingColors();
      var datasets = colours.map(function(bucketDef) {
          return {
              label: bucketDef.key,
              backgroundColor: bucketDef.color,
              data: months.map(function(m) {
                  var match = m.buckets.filter(function(b) { return b.label === bucketDef.key; })[0];
                  return match ? (match.value || 0) : 0;
              })
          };
      });

      // Set legend from first month's bucket labels
      if (months.length > 0) {
          c.ageingLegend = months[0].buckets.map(function(bucket, idx) {
              return { label: bucket.label, color: colours[idx] ? colours[idx].color : '#aaa' };
          });
      }

      if (ageingChartInstance) { try { ageingChartInstance.destroy(); } catch(e) {} }
      ageingChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar', data: { labels: labels, datasets: datasets },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ stacked: true, gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [{ stacked: true, scaleLabel: { display: true, labelString: 'Outstanding Amount (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } }]
              }
          }
      });
      registerChartVisibilityTarget(canvas, function() { return ageingChartInstance; });
  }

  angular.element($window).on('resize', function() {
    if (salesChartInstance) { salesChartInstance.resize(); }
    if (ageingChartInstance) { ageingChartInstance.resize(); }
  });

  $scope.$on('$destroy', function() {
      angular.element($window).off('resize');
      if (salesChartInstance) { try{salesChartInstance.destroy();}catch(e){} }
      if (ageingChartInstance) { try{ageingChartInstance.destroy();}catch(e){} }
  });

  // Init load with default business T00 (Trade)
  if (c.data && c.data.tableData) {
      allTimeTableData = c.data.tableData;
      c.buildRiskMatrix();
      c.applyLocalFilters();
      c.buildTrendChart();
      c.renderCharts();
  }
}

sp_widget.css:
.clm-portfolio-overview {
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #1f2933;
  padding: 0 20px 24px 20px;
}

/* ---- Filter Tracker & Clear All ---- */
.clm-filter-tracker {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  padding: 10px 16px; background: #ffffff; border-bottom: 1px solid #e3e6eb;
}
.clm-tracker-chips { display: flex; flex-wrap: wrap; gap: 6px; flex: 1; }
.clm-tracker-chip {
  display: inline-flex; align-items: center; gap: 4px; background: #f8f9fa;
  border: 1px solid #cbd5e1; border-radius: 14px; padding: 4px 12px;
  font-size: 11px; font-weight: 600; color: #4a5568; cursor: pointer; transition: 0.15s;
}
.clm-tracker-chip i.fa-times { font-size: 10px; margin-left: 4px; color: #a0aec0; transition: color 0.15s; }
.clm-tracker-chip:hover { background: #edf2f7; border-color: #a0aec0; }
.clm-tracker-chip:hover i.fa-times { color: #e53e3e; }
.clm-clear-all-btn {
  background: #fff5f5; color: #e53e3e; border: 1px solid #feb2b2; border-radius: 14px;
  padding: 4px 14px; font-size: 11px; font-weight: 600; cursor: pointer;
  transition: 0.15s; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap;
}
.clm-clear-all-btn:hover { background: #e53e3e; color: #ffffff; border-color: #e53e3e; }

/* ---- Filters ---- */
.clm-filter-card {
  margin: 0 0 16px 0; background: #fff; border: 1px solid #e3e6eb;
  border-radius: 8px; padding: 14px 18px; overflow: visible; position: relative; z-index: 20;
}
.clm-filter-row { display: flex; align-items: center; gap: 12px; flex-wrap: nowrap; overflow-x: visible; white-space: nowrap; }
.clm-filter-field { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #5b6470; margin-bottom: 0; font-weight: normal; flex: 1; position: relative; }
.clm-filter-field select {
  width: 100%; min-width: 140px; height: 34px; font-size: 13px; border-radius: 4px;
  border: 1px solid #cbd5e1; background-color: #ffffff; padding: 0 10px; outline: none; cursor: pointer; transition: all 0.2s ease;
}
.clm-filter-field select:hover { border-color: #a0aec0; background-color: #f7fafc; }

/* ---------- Multiselect Region & Depot ---------- */
.clm-multiselect-field { position: relative; }
.clm-multiselect-container { position: relative; width: 100%; min-width: 160px; }
.clm-multiselect-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 34px;
  padding: 0 10px;
  font-size: 13px;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #ffffff;
  cursor: pointer;
  box-sizing: border-box;
  transition: border-color 0.2s;
}
.clm-multiselect-trigger:hover { border-color: #a0aec0; }
.clm-multiselect-container.open .clm-multiselect-trigger { border-color: #1c4e9c; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.clm-multiselect-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #1f2933; flex: 1; }
.clm-multiselect-arrow { color: #a0aec0; font-size: 10px; margin-left: 6px; }
.clm-multiselect-dropdown {
  position: absolute;
  top: 34px; left: 0; right: 0;
  z-index: 60;
  background: #fff;
  border: 1px solid #1c4e9c;
  border-top: none;
  border-bottom-left-radius: 6px;
  border-bottom-right-radius: 6px;
  box-shadow: 0 6px 14px rgba(0,0,0,0.12);
  max-height: 280px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.clm-multiselect-actions {
  display: flex;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 1px solid #e3e6eb;
  background: #f8f9fa;
}
.clm-multiselect-actions a {
  font-size: 11px;
  color: #1c4e9c;
  cursor: pointer;
  font-weight: 600;
}
.clm-multiselect-actions a:hover { text-decoration: underline; }
.clm-multiselect-search {
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: none;
  border-bottom: 1px solid #e3e6eb;
  font-size: 12px;
  outline: none;
  box-sizing: border-box;
}
.clm-multiselect-list {
  list-style: none;
  margin: 0;
  padding: 4px 0;
  overflow-y: auto;
  max-height: 180px;
}
.clm-multiselect-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font-size: 13px;
  cursor: pointer;
  color: #1f2933;
}
.clm-multiselect-list li:hover { background: #f0f4f9; }
.clm-multiselect-list li.selected { background: #ebf5ff; }
.clm-dropdown-empty { color: #a0aec0 !important; cursor: default !important; font-style: italic; padding: 8px 12px; font-size: 13px; }
.clm-checkbox {
  width: 14px; height: 14px;
  border: 2px solid #cbd5e1;
  border-radius: 3px;
  display: inline-block;
  flex-shrink: 0;
  position: relative;
}
.clm-checkbox.checked {
  background: #1c4e9c;
  border-color: #1c4e9c;
}
.clm-checkbox.checked::after {
  content: '';
  position: absolute;
  left: 3px; top: 1px;
  width: 4px; height: 7px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* Custom searchable dropdown */
.clm-custom-dropdown { position: relative; z-index: 10; }
.clm-dropdown-wrapper { position: relative; width: 100%; min-width: 140px; }
.clm-dropdown-input {
  width: 100%; height: 34px; font-size: 13px; border-radius: 4px;
  border: 1px solid #cbd5e1; background-color: #ffffff; padding: 0 26px 0 10px;
  outline: none; cursor: pointer; transition: all 0.2s ease; box-sizing: border-box;
}
.clm-dropdown-input:hover { border-color: #a0aec0; background-color: #f7fafc; }
.clm-dropdown-input:focus { border-color: #1c4e9c; background-color: #ffffff; }
.clm-custom-dropdown.open .clm-dropdown-input { border-color: #1c4e9c; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.clm-dropdown-clear { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); color: #a0aec0; font-size: 11px; cursor: pointer; }
.clm-dropdown-clear:hover { color: #718096; }
.clm-dropdown-list {
  position: absolute; top: 34px; left: 0; right: 0; z-index: 100;
  background: #ffffff; border: 1px solid #1c4e9c; border-top: 1px solid #e3e6eb;
  border-bottom-left-radius: 6px; border-bottom-right-radius: 6px;
  box-shadow: 0 6px 14px rgba(0,0,0,0.12); max-height: 220px; overflow-y: auto; list-style: none; margin: 0; padding: 4px 0;
}
.clm-dropdown-list li { padding: 8px 12px; font-size: 13px; color: #1f2933; cursor: pointer; white-space: normal; }
.clm-dropdown-list li:hover { background-color: #f0f4f9; }
.clm-dropdown-list li.active { background-color: #4a5568; color: #ffffff; }
.clm-dropdown-empty { color: #a0aec0 !important; cursor: default !important; font-style: italic; }

/* ---- KPIs ---- */
.clm-kpi-grid { display: grid; grid-template-columns: repeat(4, minmax(160px, 1fr)); gap: 14px; margin: 16px 0; }
.clm-kpi-card {
  position: relative;
  background: #fff; border: 1px solid #e3e6eb; border-left: 4px solid #c9ced6;
  border-radius: 6px; padding: 14px 16px; min-height: 100px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.02); transition: background-color 0.3s, box-shadow 0.3s;
}
.clm-kpi-card.border-blue   { border-left-color: #1c4e9c; }
.clm-kpi-card.border-orange { border-left-color: #dd6b20; }
.clm-kpi-card.border-green  { border-left-color: #38a169; }
.clm-kpi-card.border-teal   { border-left-color: #319795; }
.clm-kpi-card.border-red    { border-left-color: #e53e3e; }
.clm-kpi-card.border-purple { border-left-color: #7c3aed; }
.clm-kpi-code { font-size: 10px; font-weight: 700; color: #718096; margin-bottom: 6px; text-transform: uppercase; }
.clm-kpi-value { font-size: 24px; font-weight: 700; }
.clm-kpi-value.large { font-size: 28px; }
.clm-kpi-sub { font-size: 11px; color: #8a93a0; margin-top: 2px; }

.clm-kpi-info { 
  position: absolute; 
  top: 10px; 
  right: 10px; 
  color: #2b6cb0;
  font-size: 15px; 
  transition: all 0.2s ease;
  cursor: pointer;
  z-index: 5;
}
.clm-kpi-info:hover { color: #1c4e9c; transform: scale(1.15); }

.text-blue   { color: #2b6cb0; }
.text-orange { color: #dd6b20; }
.text-green  { color: #38a169; }
.text-teal   { color: #319795; }
.text-red    { color: #e53e3e; }
.text-purple { color: #7c3aed; }
.clm-progress { height: 4px; border-radius: 2px; background: #edf2f7; margin-top: 10px; }
.clm-progress-fill { height: 100%; border-radius: 2px; }
.bg-blue { background: #2b6cb0; }
.bg-teal { background: #319795; }

/* ---- Charts ---- */
.clm-chart-card { background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; padding: 16px 20px; margin: 16px 0; overflow: hidden; position: relative; }
.clm-chart-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.clm-chart-title { font-size: 13px; font-weight: 700; color: #1f2933; }
.clm-chart-badge { font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 10px; }
.clm-badge-line    { background: #fff7e6; color: #b7791f; }
.clm-badge-combo   { background: #e6f0ff; color: #1c4e9c; }
.clm-badge-stacked { background: #f0e6ff; color: #6b21a8; }
.clm-badge-heatmap { background: linear-gradient(135deg, #e53e3e, #dd6b20); color: #fff; padding: 3px 10px; border-radius: 12px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }

.clm-trend-body { position: relative; height: 260px; padding-top: 10px; width: 100%; }
.clm-trend-svg { width: 100%; height: 260px; display: block; }

.clm-trend-area { fill: rgba(221, 107, 32, 0.1); }
.clm-trend-line { fill: none; stroke: #dd6b20; stroke-width: 2px; }
.clm-trend-dot { fill: #fff; stroke: #dd6b20; stroke-width: 2px; cursor: pointer; transition: r 0.2s; pointer-events: all; }
.clm-trend-dot:hover { r: 6; fill: #dd6b20; }
.clm-trend-dot.last { fill: #dd6b20; }
.clm-trend-grid line { stroke: #e2e8f0; stroke-dasharray: 4; stroke-width: 1px; }
.clm-trend-yaxis text, .clm-trend-xaxis text { font-size: 11px; fill: #718096; font-family: "Helvetica Neue", Arial, sans-serif; }
.clm-chart-empty { text-align: center; color: #a0aec0; padding: 20px; font-style: italic; }

.clm-charts-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 16px 0; }
@media (max-width: 768px) { .clm-charts-row { grid-template-columns: 1fr; } }
.clm-chart-half { margin: 0; overflow: hidden; position: relative; }

.clm-charts-row .clm-chart-wrapper {
  position: relative;
  height: 240px;
  width: 100%;
  padding: 10px 16px;
  box-sizing: border-box;
}
.clm-charts-row .clm-chart-wrapper canvas {
  width: 100% !important;
  height: 100% !important;
}

.clm-ageing-legend {
  display: flex; justify-content: center; gap: 20px; flex-wrap: wrap;
  margin-top: 14px; padding: 8px 0 4px 0;
}
.clm-legend-item { display: flex; align-items: center; gap: 6px; font-size: 12.5px; color: #334155; font-weight: 600; }
.clm-legend-color { width: 14px; height: 14px; border-radius: 3px; display: inline-block; }

/* Pie-style breadcrumb for Heatmap */
.clm-pie-breadcrumb { font-size: 12px; color: #718096; }
.clm-pie-breadcrumb .crumb { cursor: pointer; padding: 2px 4px; }
.clm-pie-breadcrumb .crumb.active { font-weight: 700; color: #1c4e9c; cursor: default; }
.clm-pie-breadcrumb .crumb:not(.active):hover { text-decoration: underline; }

/* ===================== REGION RISK HEATMAP ===================== */
.clm-heatmap-card { }
.clm-heatmap-container { padding: 16px 20px; }
.clm-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #e2e8f0;
}
.clm-legend-label { font-size: 12px; font-weight: 600; color: #4a5568; }
.clm-legend-gradient { display: flex; gap: 2px; }
.clm-legend-color { width: 24px; height: 14px; border-radius: 2px; }
.clm-legend-text { font-size: 11px; color: #718096; }

.clm-heatmap-matrix {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 1fr;
  gap: 2px;
  background: #ffffff;
  border: 0px solid #e2e8f0;
  border-radius: 8px;
  overflow: hidden;
}

.clm-matrix-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 70px;
  cursor: pointer;
  position: relative;
  transition: outline 0.15s ease, outline-offset 0.15s ease;
  background-color: transparent;   
}

.clm-matrix-cell:hover {
  outline: 2px solid #3182ce;
  outline-offset: -2px;
}

.clm-matrix-cell.selected {
  outline: 3px solid #3182ce;
  outline-offset: -3px;
}

.clm-cell-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8px 4px;
  pointer-events: none;
}

.clm-cell-region { font-size: 14px; font-weight: 700; line-height: 1.2; margin-bottom: 4px; }
.clm-cell-badges { display: flex; gap: 4px; flex-wrap: wrap; justify-content: center; }
.clm-cell-badge {
  padding: 0px 6px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3px;
  background: rgba(255, 255, 255, 0.85);
  border: 1px solid rgba(0,0,0,0.15);
  line-height: 16px;
}

.clm-badge-h { color: #c53030; }
.clm-badge-m { color: #9c4221; }
.clm-badge-l { color: #276749; }

.clm-heatmap-tooltip {
  position: absolute;
  background: rgba(15, 15, 15, 0.95);
  color: #fff;
  padding: 14px 18px;
  border-radius: 10px;
  font-size: 12.5px;
  z-index: 1000;
  pointer-events: none;
  box-shadow: 0 10px 25px rgba(0,0,0,0.35);
  min-width: 200px;
  transition: left 0.1s ease, top 0.1s ease;
  backdrop-filter: blur(4px);
}
.clm-heatmap-tooltip .clm-tooltip-title {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255,255,255,0.25);
}
.clm-heatmap-tooltip .clm-tooltip-row { margin-bottom: 5px; font-size: 12.5px; line-height: 1.3; }

/* ===================== TABLE SECTION ===================== */
.clm-table-container { margin: 16px 0; background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; overflow: hidden; position: relative; transition: opacity 0.3s; }
.clm-chip-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 12px 16px; background: #fff; border-bottom: 1px solid #e3e6eb; }
.clm-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px;
  font-size: 12px; font-weight: 600; color: #4a5568; background: #f8f9fa;
  border: 1px solid #e2e8f0; border-radius: 16px; cursor: pointer; transition: all 0.15s ease;
}
.clm-chip:hover { background: #eef2f7; border-color: #cbd5e1; }
.clm-chip.active { background: #1c4e9c; border-color: #1c4e9c; color: #ffffff; }
.clm-chip .clm-chip-count { background: rgba(0,0,0,0.08); color: inherit; border-radius: 10px; padding: 1px 7px; font-size: 11px; }
.clm-chip.active .clm-chip-count { background: rgba(255,255,255,0.25); }
.clm-chip-warn i   { color: #975a16; }
.clm-chip-orange i { color: #dd6b20; }
.clm-chip-blue i   { color: #1c4e9c; }
.clm-chip-red i    { color: #e53e3e; }
.clm-chip.active i { color: #ffffff; }

.clm-chip-purple {
  background: #f3e8ff;
  color: #7c3aed;
  border: 1px solid #d8b4fe;
}
.clm-chip-purple.active,
.clm-chip-purple:hover {
  background: #7c3aed;
  color: #fff;
  border-color: #7c3aed;
}
.clm-chip-purple.active .clm-chip-count,
.clm-chip-purple:hover .clm-chip-count {
  background: rgba(255,255,255,0.25);
  color: #fff;
}

/* Green chip (High Growth 20) */
.clm-chip-green { background: #e6fffa; color: #2c7a7b; border: 1px solid #b2f5ea; }
.clm-chip-green.active,
.clm-chip-green:hover { background: #2c7a7b; color: #fff; border-color: #2c7a7b; }
.clm-chip-green.active .clm-chip-count,
.clm-chip-green:hover .clm-chip-count { background: rgba(255,255,255,0.25); color: #fff; }

.clm-selected-region-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  background: #3182ce;
  border: 1px solid #3182ce;
  border-radius: 16px;
  animation: fadeInChip 0.3s ease;
}
.clm-selected-region-chip i.fa-times {
  cursor: pointer;
  font-size: 11px;
  opacity: 0.8;
  transition: opacity 0.2s;
}
.clm-selected-region-chip i.fa-times:hover { opacity: 1; }

.clm-filters-transition-wrapper {
  max-height: 200px;
  overflow: hidden;
  transition: max-height 0.35s ease, opacity 0.35s ease, padding 0.35s ease;
  opacity: 1;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid #e3e6eb;
}
.clm-filters-transition-wrapper.collapsing {
  max-height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.clm-active-filters-inline {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
}
.clm-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #f7fafc;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 2px 10px;
  font-size: 11px;
  font-weight: 600;
  color: #2d3748;
  white-space: nowrap;
  animation: fadeInChip 0.25s ease;
}
@keyframes fadeInChip {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}
.clm-filter-chip i { cursor: pointer; color: #a0aec0; font-size: 10px; transition: color 0.2s; }
.clm-filter-chip i:hover { color: #e53e3e; }
.clm-clear-all-inline {
  background: none;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  color: #e53e3e;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
  transition: background 0.2s;
}
.clm-clear-all-inline:hover { background: #fff5f5; }

.clm-table-toolbar-top { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: #fff; border-bottom: 1px solid #e3e6eb; }
.clm-search-box { position: relative; display: flex; align-items: center; flex: 1; max-width: 320px; }
.clm-search-box i { position: absolute; left: 12px; color: #a0aec0; font-size: 13px; }
.clm-search-box input {
  width: 100%; height: 34px; padding: 0 10px 0 32px; border: 1px solid #cbd5e1;
  border-radius: 6px; font-size: 13px; outline: none; transition: border 0.2s;
}
.clm-search-box input:focus { border-color: #1c4e9c; }
.clm-table-controls-right { display: flex; align-items: center; font-size: 12px; color: #4a5568; }
.clm-table-controls-right select { border: 1px solid #cbd5e1; border-radius: 4px; padding: 4px; height: 32px; outline: none; background: #fff; cursor: pointer; margin-left: 8px; }
.clm-record-count { font-weight: 600; }
.clm-badge-blue { background: #ebf8ff; color: #1c4e9c; padding: 4px 8px; border-radius: 12px; font-size: 11px; margin-left: 4px; }

.clm-table-wrapper { 
  max-height: 450px; 
  height: auto; 
  overflow-y: auto; 
  overflow-x: auto; 
  -webkit-overflow-scrolling: touch; 
  width: 100%; 
}

.clm-table { width: 100%; border-collapse: collapse; table-layout: auto; }
.clm-table thead th {
  position: sticky; top: 0; z-index: 10; text-align: left; padding: 10px 6px;
  background: #f8f9fa; color: #718096; font-weight: 600; text-transform: uppercase;
  font-size: 9px; border-bottom: 2px solid #cbd5e1; box-shadow: 0 2px 2px -1px rgba(0,0,0,0.1);
  white-space: normal !important;
  vertical-align: bottom;
  line-height: 1.2;
}
.clm-table td {
  padding: 8px 6px; border-bottom: 1px solid #edf2f7; color: #1f2933;
  font-size: 10.5px; vertical-align: middle;
  white-space: normal !important;
}

.clm-table td.wrap-text {
  white-space: normal !important;
  word-break: break-word;
}

.clm-table tbody tr { height: auto; }
.clm-table tbody tr:hover { background-color: #f7fafc; }

.clm-table-footer { display: flex; justify-content: flex-end; align-items: center; padding: 10px 16px; background: #f8f9fa; border-top: 1px solid #e3e6eb; position: sticky; bottom: 0; z-index: 10; }
.clm-page-numbers { display: flex; gap: 4px; }
.clm-page-btn { background: #fff; border: 1px solid #cbd5e1; border-radius: 4px; height: 32px; min-width: 32px; cursor: pointer; color: #4a5568; font-weight: 600; display: flex; align-items: center; justify-content: center; }
.clm-page-btn:hover:not(:disabled) { background: #eef2f7; }
.clm-page-btn.active { background: #1c4e9c; color: #fff; border-color: #1c4e9c; }
.clm-page-btn:disabled { color: #a0aec0; background: #f8f9fa; cursor: not-allowed; border-color: #e2e8f0; }

.clm-nowrap { white-space: nowrap !important; }
.clm-code { color: #2b6cb0; font-weight: 600; cursor: pointer; }
.clm-sub-pan { display: block; font-size: 10px; color: #718096; margin-top: 2px; }

.clm-pill-status { padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; white-space: nowrap; }
.status-approved  { background: #e3f4ea; color: #1f7a4d; }
.status-submitted { background: #fffdf0; color: #975a16; }
.status-norequest { background: #f0f4f9; color: #1f2933; }
.clm-hg-yes { background: #e6fffa; color: #2c7a7b; }
.clm-hg-no  { background: #f7fafc; color: #718096; }

.seg-cement  { background: #ede9fe; color: #5b21b6; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-bpd     { background: #fffdf0; color: #975a16; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-default { background: transparent; color: #1f2933; font-weight: 500; }

.clm-strong { font-weight: 600; }
.clm-text-red { color: #e53e3e !important; font-weight: 600; }
.clm-text-orange { color: #dd6b20 !important; font-weight: 600; }
.clm-text-green { color: #38a169 !important; font-weight: 600; }
.clm-mini-progress { width: 32px; height: 4px; background: #edf2f7; border-radius: 2px; }
.clm-mini-fill { height: 100%; border-radius: 2px; background: currentColor; }

.clm-content-wrap { position: relative; min-height: 200px; }
.clm-content-wrap.clm-loading-active > *:not(.clm-loading-overlay) { opacity: 0.35; filter: blur(1px); pointer-events: none; transition: opacity 0.2s ease; }
.clm-loading-overlay { position: absolute; inset: 0; z-index: 60; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding-top: 60px; background: rgba(255,255,255,0.7); }
.clm-spinner { width: 34px; height: 34px; border: 3px solid #dbe3ee; border-top-color: #1c4e9c; border-radius: 50%; animation: clm-spin 0.7s linear infinite; }
.clm-loading-text { font-size: 13px; font-weight: 600; color: #4a5568; }
@keyframes clm-spin { to { transform: rotate(360deg); } }

sp_widget.script:
(function() {
    // ======================= TABLE DEFINITIONS =======================
    var TRADE_TABLES = {
        master:   'x_birl3_clm_clm_customer_master1',
        request:  'x_birl3_clm_clm_new_credit_request',
        snapshot: 'x_birl3_clm_clm_aging_snapshot',
        roleMap:  'x_birl3_clm_role_user_mapping',
        salesValue: 'x_birl3_clm_clm_cement_rmc_bpd_values',
        salesVol:   'x_birl3_clm_clm_sales_data'
    };

    var NONTRADE_TABLES = {
        master:   'x_birl3_clm_customer',
        request:  'x_birl3_clm_non_trade_clr',
        snapshot: 'x_birl3_clm_customer_outstanding',
        roleMap:  'x_birl3_clm_approval_matrix',
        salesValue: 'x_birl3_clm_clm_cement_rmc_bpd_values',   // shared
        salesVol:   'x_birl3_clm_clm_sales_data'                // shared
    };

    // ======================= INPUT =======================
    var inputFilters = (input && input.filters) ? input.filters : {
        business: 'T00',
        period: 'latest',
        zones: [],
        regions: [],
        depot: '',
        segment: ''
    };

    var business = inputFilters.business || 'T00';
    var isTrade = (business === 'T00');
    var isNonTrade = (business === 'N01');
    var isAll = (business === 'ALL');

    // ======================= HELPERS =======================
    function normArray(v) {
        if (typeof v === 'string') {
            try { v = JSON.parse(v); } catch(e) { v = v ? [v] : []; }
        }
        if (!Array.isArray(v)) v = v ? [v] : [];
        return v;
    }
    inputFilters.zones   = normArray(inputFilters.zones);
    inputFilters.regions = normArray(inputFilters.regions);

    function extractCode(val) {
        if (!val) return '';
        var m = val.match(/\(([^)]+)\)$/);
        return m ? m[1] : val;
    }
    function extractCodes(arr) { return arr.map(extractCode).filter(Boolean); }

    function formatNameCode(name, code) {
        if (name && code && name !== code) return name + ' (' + code + ')';
        return name || code || '';
    }

    function getSafeCode(gr, field) {
        var v = gr.getValue(field) || '';
        if (v.length === 32 && /^[0-9a-f]{32}$/i.test(v)) {
            v = gr.getDisplayValue(field) || '';
        }
        return v;
    }

    var gdtToday = new GlideDateTime();
    var currentUserId = gs.getUserID();
    var MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var monthNamesLower = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    function pad2(n) { return n < 10 ? '0' + n : '' + n; }

    // NT segment mapping
    var NT_SEG_MAP = { 'UTCL': 'Cement', 'URMX': 'RMC', 'GIL': 'BPD' };
    function ntSegLabel(raw) { return NT_SEG_MAP[raw] || raw; }
    var NT_SEG_REVERSE = { 'Cement': 'UTCL', 'RMC': 'URMX', 'BPD': 'GIL' };

    // ==== High Growth config (Trade only) ====
    var HIGH_GROWTH_SALES_FIELDS = ['u_jun_25','u_jul_25','u_aug_25','u_sep_25','u_oct_25','u_nov_25',
                                    'u_dec_25','u_jan_26','u_feb_26','u_mar_26','u_apr_26','u_may_26'];
    var HIGH_GROWTH_THRESHOLD_PCT = 110;

    // ======================= PERIOD =======================
    var period = inputFilters.period || 'latest';
    var now = new Date();
    var currentYear = now.getFullYear();
    var currentMonth = now.getMonth();
    var reqEndDate = '';
    if (period === 'latest' || period === 'this_month') {
        var lastDay = new Date(currentYear, currentMonth + 1, 0).getDate();
        reqEndDate = currentYear + '-' + pad2(currentMonth + 1) + '-' + pad2(lastDay) + ' 23:59:59';
    } else if (period === 'last_month') {
        var lm = new Date(currentYear, currentMonth - 1, 1);
        var lmYear = lm.getFullYear(), lmMonth = lm.getMonth() + 1;
        var lmLastDay = new Date(lmYear, lmMonth, 0).getDate();
        reqEndDate = lmYear + '-' + pad2(lmMonth) + '-' + pad2(lmLastDay) + ' 23:59:59';
    } else if (period === 'this_year') {
        reqEndDate = currentYear + '-12-31 23:59:59';
    } else if (period === 'last_year') {
        reqEndDate = (currentYear - 1) + '-12-31 23:59:59';
    }

    // ======================= ACCESS CONTROL =======================
    var isAdmin = false;
    var grAdmin = new GlideRecord('sys_user_has_role');
    grAdmin.addQuery('user', currentUserId);
    grAdmin.addQuery('role.name', 'admin');
    grAdmin.query();
    if (grAdmin.hasNext()) isAdmin = true;

    if (!isAdmin) {
        var authorized = false;
        if (isTrade || isAll) {
            var grTradeCCH = new GlideRecord(TRADE_TABLES.roleMap);
            grTradeCCH.addQuery('u_user', currentUserId);
            grTradeCCH.addQuery('u_role', 'CCH');
            grTradeCCH.query();
            if (grTradeCCH.hasNext()) authorized = true;
        }
        if (isNonTrade || isAll) {
            var grNT = new GlideRecord(NONTRADE_TABLES.roleMap);
            grNT.addQuery('approver_user', currentUserId);
            grNT.addQuery('role_name', 'IN', ['Cement CCH', 'RMC CCH', 'BPD CCH']);
            grNT.query();
            if (grNT.hasNext()) authorized = true;
        }
        if (!authorized) {
            data.filterOpts = { zones:[], regions:[], segments:[], depots:[], periods:[], business:business };
            data.tableData = []; data.kpis = {};
            return;
        }
    }

    // ======================= FILTER OPTIONS (OBJECTS) =======================
    function buildTradeFilterOptions() {
        var zones = [], regions = [], depots = [], segments = [];
        var ga = new GlideAggregate(TRADE_TABLES.master);
        ga.groupBy('zone_name'); ga.groupBy('zone'); ga.query();
        while (ga.next()) {
            var n = ga.getValue('zone_name') || '', c = getSafeCode(ga, 'zone');
            zones.push({ value: c, label: formatNameCode(n, c) });
        }
        ga = new GlideAggregate(TRADE_TABLES.master);
        ga.groupBy('region_name'); ga.groupBy('region'); ga.query();
        while (ga.next()) {
            var n = ga.getValue('region_name') || '', c = getSafeCode(ga, 'region');
            regions.push({ value: c, label: formatNameCode(n, c) });
        }
        ga = new GlideAggregate(TRADE_TABLES.master);
        ga.groupBy('depot_name'); ga.groupBy('depot'); ga.query();
        while (ga.next()) {
            var n = ga.getValue('depot_name') || '', c = getSafeCode(ga, 'depot');
            depots.push({ value: c, label: formatNameCode(n, c) });
        }
        ga = new GlideAggregate(TRADE_TABLES.master);
        ga.groupBy('segment'); ga.query();
        while (ga.next()) {
            var seg = ga.getValue('segment');
            if (seg) segments.push({ value: seg, label: seg });
        }
        return {
            zones: zones.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            regions: regions.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            depots: depots.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            segments: segments.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            periods: [
                { label: 'All Time (Latest)', value: 'latest' },
                { label: 'This Month', value: 'this_month' },
                { label: 'Last Month', value: 'last_month' },
                { label: 'This Year', value: 'this_year' },
                { label: 'Last Year', value: 'last_year' }
            ]
        };
    }

    function buildNTFilterOptions() {
        var zones = [], regions = [], depots = [], segments = [];
        var ga = new GlideAggregate(NONTRADE_TABLES.master);
        ga.groupBy('customer_group'); ga.query();
        while (ga.next()) {
            var v = ga.getValue('customer_group');
            if (v) zones.push({ value: v, label: v });
        }
        ga = new GlideAggregate(NONTRADE_TABLES.master);
        ga.groupBy('cg4'); ga.query();
        while (ga.next()) {
            var v = ga.getValue('cg4');
            if (v) regions.push({ value: v, label: v });
        }
        ga = new GlideAggregate(NONTRADE_TABLES.master);
        ga.groupBy('sales_office'); ga.query();
        while (ga.next()) {
            var v = ga.getValue('sales_office');
            if (v) depots.push({ value: v, label: v });
        }
        ga = new GlideAggregate(NONTRADE_TABLES.master);
        ga.groupBy('company_code'); ga.query();
        while (ga.next()) {
            var raw = ga.getValue('company_code');
            if (raw) segments.push({ value: raw, label: ntSegLabel(raw) });
        }
        return {
            zones: zones.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            regions: regions.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            depots: depots.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            segments: segments.sort(function(a,b){ return a.label.localeCompare(b.label); }),
            periods: [
                { label: 'All Time (Latest)', value: 'latest' },
                { label: 'This Month', value: 'this_month' },
                { label: 'Last Month', value: 'last_month' },
                { label: 'This Year', value: 'this_year' },
                { label: 'Last Year', value: 'last_year' }
            ]
        };
    }

    // ======================= PROCESS ONE MODE (with segment override) =======================
    function processMode(isTradeMode, segmentOverride) {
        var tables = isTradeMode ? TRADE_TABLES : NONTRADE_TABLES;
        var activeZones = extractCodes(inputFilters.zones);
        var activeRegions = extractCodes(inputFilters.regions);
        var activeDepot = extractCode(inputFilters.depot);
        var segFilter = (segmentOverride !== undefined) ? segmentOverride : (inputFilters.segment || '');

        // --- Master records ---
        var master = [];
        var grCust = new GlideRecord(tables.master);
        if (isTradeMode) {
            if (activeZones.length) grCust.addQuery('zone', 'IN', activeZones);
            if (activeRegions.length) grCust.addQuery('region', 'IN', activeRegions);
            if (activeDepot) grCust.addQuery('depot', activeDepot);
            if (segFilter) grCust.addQuery('segment', segFilter);
        } else {
            if (activeZones.length) grCust.addQuery('customer_group', 'IN', activeZones);
            if (activeRegions.length) grCust.addQuery('cg4', 'IN', activeRegions);
            if (activeDepot) grCust.addQuery('sales_office', activeDepot);
            if (segFilter) grCust.addQuery('company_code', segFilter);
        }
        grCust.query();
        var sysIds = [];
        while (grCust.next()) {
            var sid = grCust.getUniqueValue();
            sysIds.push(sid);
            var code = isTradeMode ? grCust.getValue('customer_code_sap') : grCust.getValue('customer_code');
            var name = isTradeMode ? grCust.getValue('customer_name') : grCust.getValue('name');
            var pan = grCust.getValue('pan') || '';
            var segment = isTradeMode ? grCust.getDisplayValue('segment') : ntSegLabel(grCust.getValue('company_code'));
            var zone = isTradeMode
                ? formatNameCode(grCust.getValue('zone_name'), getSafeCode(grCust, 'zone'))
                : (grCust.getValue('customer_group') || '');
            var region = isTradeMode
                ? formatNameCode(grCust.getValue('region_name'), getSafeCode(grCust, 'region'))
                : (grCust.getValue('cg4') || '');
            var depot = isTradeMode
                ? formatNameCode(grCust.getValue('depot_name'), getSafeCode(grCust, 'depot'))
                : (grCust.getValue('sales_office') || '');
            var creditLimit = isTradeMode ? 0 : (parseFloat(grCust.getValue('credit_limit')) || 0);
            var reviewDate = isTradeMode ? '' : grCust.getValue('next_review_date') || '';
            master.push({
                sysId: sid, code: code, name: name, pan: pan, segment: segment,
                zone: zone, region: region, depot: depot,
                creditLimit: creditLimit, reviewDate: reviewDate
            });
        }

        // --- Trend month list ---
        var sixMonths = [];
        for (var i = 5; i >= 0; i--) {
            var d = new Date(currentYear, currentMonth - i, 1);
            sixMonths.push({ year: d.getFullYear(), month: d.getMonth() });
        }

        // --- Request / Snapshot / Sales maps ---
        var reqMap = {}, snapMap = {};
        var customerSalesMap = {};          // for OS/Sales (6M)
        var outstandingSumMap = {};
        var salesTrendMap = {}, volumeTrendMap = {};
        sixMonths.forEach(function(m) {
            var ym = m.year + '-' + pad2(m.month + 1);
            salesTrendMap[ym] = 0;
            volumeTrendMap[ym] = 0;
        });

        // For High Growth (Trade only)
        var highGrowthSalesMap = {};

        if (sysIds.length > 0) {
            var chunks = [];
            var tmp = sysIds.slice();
            while (tmp.length) chunks.push(tmp.splice(0, 2000));

            for (var ci = 0; ci < chunks.length; ci++) {
                var chunk = chunks[ci];

                // --- Request ---
                var grReq = new GlideRecord(tables.request);
                if (isTradeMode) {
                    grReq.addQuery('customer', 'IN', chunk);
                } else {
                    grReq.addQuery('customer_code', 'IN', chunk);
                }
                if (reqEndDate) grReq.addQuery('sys_created_on', '<=', reqEndDate);
                grReq.orderByDesc('sys_created_on');
                grReq.query();
                while (grReq.next()) {
                    var cid = isTradeMode ? grReq.getValue('customer') : grReq.getValue('customer_code');
                    if (!reqMap[cid]) {
                        if (isTradeMode) {
                            reqMap[cid] = {
                                approvedLimit: parseFloat(grReq.getValue('approved_limit')) || 0,
                                currentCreditLimit: parseFloat(grReq.getValue('current_credit_limit')) || 0,
                                outstanding: parseFloat(grReq.getValue('outstanding_amount')) || 0,
                                grossExp: parseFloat(grReq.getValue('net_exposure')) || 0,
                                status: grReq.getDisplayValue('state') || 'Active',
                                stateRaw: (grReq.getValue('state') || '').toLowerCase(),
                                reviewDate: grReq.getValue('next_review_date') || '',
                                activeSd: parseFloat(grReq.getValue('active_sd')) || 0,
                                expectedPotential: parseFloat(grReq.getValue('u_tool_expected_potential')) || 0
                            };
                        } else {
                            var appDisp = grReq.getDisplayValue('approval') || '';
                            var appVal = (grReq.getValue('approval') || '').toLowerCase();
                            if (!appVal && !appDisp) { appDisp = 'Active'; appVal = 'active'; }
                            reqMap[cid] = {
                                approvedLimit: parseFloat(grReq.getValue('approved_limit')) || 0,
                                currentCreditLimit: parseFloat(grReq.getValue('credit_limit')) || 0,
                                outstanding: 0,
                                grossExp: parseFloat(grReq.getValue('net_exposure')) || 0,
                                status: appDisp,
                                stateRaw: appVal,
                                reviewDate: grReq.getValue('next_review_date') || '',
                                activeSd: 0
                            };
                        }
                    }
                }

                // --- Snapshot ---
                var grSnap = new GlideRecord(tables.snapshot);
                grSnap.addQuery('customer', 'IN', chunk);
                if (isTradeMode) {
                    if (reqEndDate) grSnap.addQuery('snapshot_month', '<=', reqEndDate);
                    grSnap.orderByDesc('snapshot_month');
                } else {
                    if (reqEndDate) grSnap.addQuery('created_on', '<=', reqEndDate);
                    grSnap.orderByDesc('created_on');
                }
                grSnap.query();
                while (grSnap.next()) {
                    var cid2 = grSnap.getValue('customer');
                    if (!snapMap[cid2]) {
                        if (isTradeMode) {
                            snapMap[cid2] = {
                                totalOutstanding: parseFloat(grSnap.getValue('total_outstanding')) || 0,
                                b0_30: (parseFloat(grSnap.getValue('bucket_0_30_days')) || 0) + (parseFloat(grSnap.getValue('bucket_22_30_days')) || 0),
                                b31_60: (parseFloat(grSnap.getValue('bucket_31_45_days')) || 0) + (parseFloat(grSnap.getValue('bucket_46_60_days')) || 0),
                                b61_90: (parseFloat(grSnap.getValue('bucket_61_75_days')) || 0) + (parseFloat(grSnap.getValue('bucket_76_90_days')) || 0),
                                b91_120: parseFloat(grSnap.getValue('bucket_91_120_days')) || 0,
                                b121_180: parseFloat(grSnap.getValue('bucket_121_180_days')) || 0,
                                b181_365: parseFloat(grSnap.getValue('bucket_181_365_days')) || 0,
                                b366_730: parseFloat(grSnap.getValue('bucket_366_730_days')) || 0,
                                b730_above: parseFloat(grSnap.getValue('bucket_730_above')) || 0
                            };
                        } else {
                            snapMap[cid2] = {
                                totalOutstanding: parseFloat(grSnap.getValue('outstanding')) || 0,
                                b0_30: (parseFloat(grSnap.getValue('ageing0_3')) || 0) + (parseFloat(grSnap.getValue('ageing4_7')) || 0) + (parseFloat(grSnap.getValue('ageing8_21')) || 0) + (parseFloat(grSnap.getValue('ageing22_30')) || 0),
                                b31_60: (parseFloat(grSnap.getValue('ageing31_45')) || 0) + (parseFloat(grSnap.getValue('ageing46_60')) || 0),
                                b61_90: (parseFloat(grSnap.getValue('ageing61_75')) || 0) + (parseFloat(grSnap.getValue('ageing76_90')) || 0),
                                bGt90: parseFloat(grSnap.getValue('ageing_gt90')) || 0
                            };
                        }
                    }
                }

                // --- Sales and volume (shared) ---
                var grSales = new GlideRecord(tables.salesValue);
                grSales.addQuery('u_customer', 'IN', chunk);
                if (!isTradeMode) grSales.addQuery('segment', 'NT Customer');
                grSales.query();
                while (grSales.next()) {
                    var custId = grSales.getValue('u_customer');
                    if (!custId) continue;

                    // OS/Sales ratio (6M)
                    if (!customerSalesMap[custId]) {
                        var sumSales6M = 0;
                        for (var mIdx = 0; mIdx < sixMonths.length; mIdx++) {
                            var m = sixMonths[mIdx];
                            var col = 'u_' + monthNamesLower[m.month] + '_' + String(m.year).slice(-2);
                            if (grSales.isValidField(col)) sumSales6M += parseFloat(grSales.getValue(col)) || 0;
                        }
                        customerSalesMap[custId] = sumSales6M;
                    }
                    // Trend maps (6M)
                    sixMonths.forEach(function(m) {
                        var col = 'u_' + monthNamesLower[m.month] + '_' + String(m.year).slice(-2);
                        if (grSales.isValidField(col)) {
                            var ym = m.year + '-' + pad2(m.month + 1);
                            salesTrendMap[ym] += parseFloat(grSales.getValue(col)) || 0;
                        }
                    });

                    // High Growth: compute average monthly sales over fixed 12 months (Trade only)
                    if (isTradeMode && !highGrowthSalesMap[custId]) {
                        var sumHG = 0, cntHG = 0;
                        for (var h = 0; h < HIGH_GROWTH_SALES_FIELDS.length; h++) {
                            var hCol = HIGH_GROWTH_SALES_FIELDS[h];
                            if (grSales.isValidField(hCol)) {
                                var val = parseFloat(grSales.getValue(hCol));
                                if (!isNaN(val)) {
                                    sumHG += val;
                                    cntHG++;
                                }
                            }
                        }
                        var avgMonthly = cntHG > 0 ? (sumHG / cntHG) : 0;
                        highGrowthSalesMap[custId] = avgMonthly;
                    }
                }

                var grVol = new GlideRecord(tables.salesVol);
                grVol.addQuery('u_customer', 'IN', chunk);
                if (!isTradeMode) grVol.addQuery('segment', 'NT Customer');
                grVol.query();
                while (grVol.next()) {
                    sixMonths.forEach(function(m) {
                        var col = 'u_' + monthNamesLower[m.month] + '_' + String(m.year).slice(-2);
                        if (grVol.isValidField(col)) {
                            var ym = m.year + '-' + pad2(m.month + 1);
                            volumeTrendMap[ym] += parseFloat(grVol.getValue(col)) || 0;
                        }
                    });
                }

                // OS/Sales ratio – trade only Jan 2026 onwards
                if (isTradeMode) {
                    var janStart = '2026-01-01 00:00:00';
                    var janEnd = (function(){
                        var lastDayJan = new Date(currentYear, currentMonth + 1, 0).getDate();
                        return currentYear + '-' + pad2(currentMonth + 1) + '-' + pad2(lastDayJan) + ' 23:59:59';
                    })();
                    var gaOutSum = new GlideAggregate(tables.snapshot);
                    gaOutSum.addQuery('customer', 'IN', chunk);
                    gaOutSum.addQuery('snapshot_month', '>=', janStart);
                    gaOutSum.addQuery('snapshot_month', '<=', janEnd);
                    gaOutSum.addAggregate('SUM', 'total_outstanding');
                    gaOutSum.groupBy('customer');
                    gaOutSum.query();
                    while (gaOutSum.next()) {
                        var cid4 = gaOutSum.getValue('customer');
                        if (cid4) outstandingSumMap[cid4] = parseFloat(gaOutSum.getAggregate('SUM', 'total_outstanding')) || 0;
                    }
                }
            }
        }

        // --- Build table rows & KPIs ---
        var totalLimit = 0, totalOutst = 0, totalOverdue = 0, totalOd90 = 0, totalGross = 0;
        var expCnt = 0, pendingCnt = 0, sendBackCnt = 0, rejectCnt = 0, totalActiveSd = 0;
        var tableData = [];

        for (var j = 0; j < master.length; j++) {
            var cust = master[j];
            var req = reqMap[cust.sysId] || null;
            var snap = snapMap[cust.sysId] || { totalOutstanding:0, b0_30:0, b31_60:0, b61_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0, bGt90:0 };

            var limit = isTradeMode ? (req ? req.currentCreditLimit : 0) : cust.creditLimit;
            var outstanding = isTradeMode ? (req ? req.outstanding : snap.totalOutstanding) : snap.totalOutstanding;

            var overdue_lt_60 = snap.b0_30 + snap.b31_60;
            var overdue_60_90 = snap.b61_90;
            var overdue_gt_90 = isTradeMode
                ? (snap.b91_120 + snap.b121_180 + snap.b181_365 + snap.b366_730 + snap.b730_above)
                : (snap.bGt90 || 0);
            var rowOverdue = overdue_lt_60 + overdue_60_90 + overdue_gt_90;

            var risk = 'No Overdue';
            var riskClass = '';
            if (overdue_gt_90 > 0) { risk = 'High'; riskClass = 'clm-text-red'; }
            else if (overdue_60_90 > 0) { risk = 'Medium'; riskClass = 'clm-text-orange'; }
            else if (overdue_lt_60 > 0) { risk = 'Low'; riskClass = 'clm-text-green'; }

            var displayStatus = req ? req.status : 'No Request';
            var statLower = (req ? req.stateRaw : '').toLowerCase();
            var cssClass = '';
            if (isTradeMode) {
                if (statLower.indexOf('submit') > -1 || statLower.indexOf('pend') > -1) {
                    displayStatus = 'Pending'; cssClass = 'status-submitted'; pendingCnt++;
                } else if (statLower.indexOf('reject') > -1) {
                    rejectCnt++; cssClass = 'status-rejected';
                } else if (statLower.indexOf('approv') > -1) {
                    cssClass = 'status-approved';
                }
                if (statLower.indexOf('send') > -1 || statLower.indexOf('back') > -1) sendBackCnt++;
            } else {
                if (statLower.indexOf('request') > -1 || statLower.indexOf('submit') > -1 || statLower.indexOf('pend') > -1) {
                    displayStatus = 'Pending'; cssClass = 'status-submitted'; pendingCnt++;
                } else if (statLower.indexOf('approv') > -1) {
                    cssClass = 'status-approved';
                } else if (statLower.indexOf('reject') > -1) {
                    displayStatus = 'Rejected'; cssClass = 'status-rejected'; rejectCnt++;
                }
                if (statLower.indexOf('send') > -1 || statLower.indexOf('back') > -1) sendBackCnt++;
            }
            if (!cssClass) cssClass = 'status-' + (displayStatus || '').toLowerCase().replace(/\s+/g, '-');

            totalLimit += limit;
            totalOutst += outstanding;
            totalOverdue += rowOverdue;
            totalOd90 += overdue_gt_90;
            totalGross += (req ? req.grossExp : 0);
            totalActiveSd += (req ? req.activeSd || 0 : 0);

            var reviewDays = '--', reviewColor = '';
            if (cust.reviewDate) {
                var diff = GlideDateTime.subtract(gdtToday, new GlideDateTime(cust.reviewDate)).getRoundedDayPart();
                if (diff >= 0 && diff <= 15) expCnt++;
                reviewDays = diff + 'd';
                reviewColor = diff <= 15 ? 'clm-text-red' : (diff <= 30 ? 'clm-text-orange' : 'clm-text-green');
            }

            var util = limit > 0 ? Math.round((outstanding / limit) * 100) : 0;
            var available = limit - outstanding;

            var custOutSum = outstandingSumMap[cust.sysId] || 0;
            var custSalesSum = customerSalesMap[cust.sysId] || 0;
            var osSalesRatio = custSalesSum > 0 ? (custOutSum / custSalesSum) : 0;

            // High Growth (Trade only)
            var avgMonthlySales = highGrowthSalesMap[cust.sysId] || 0;
            var expectedPotential = (req && isTradeMode) ? (req.expectedPotential || 0) : 0;
            var growthPct = expectedPotential > 0 ? (avgMonthlySales / expectedPotential) * 100 : 0;
            var highGrowth20 = (isTradeMode && growthPct > HIGH_GROWTH_THRESHOLD_PCT) ? 'Yes' : 'No';

            tableData.push({
                sysId: cust.sysId,
                code: cust.code,
                name: cust.name,
                pan: cust.pan,
                segment: cust.segment,
                segmentClass: 'seg-' + (cust.segment || '').toLowerCase().replace(/\s+/g, '-'),
                zoneName: cust.zone,
                regionName: cust.region,
                depotName: cust.depot,
                status: displayStatus,
                statusClass: cssClass,
                outstanding: outstanding,
                limit: limit,
                available: available,
                util: util,
                utilClass: util > 90 ? 'clm-text-red' : (util > 75 ? 'clm-text-orange' : 'clm-text-green'),
                od90: overdue_gt_90,
                risk: risk,
                riskClass: riskClass,
                reviewIn: reviewDays,
                reviewColor: reviewColor,
                osSalesRatio: osSalesRatio,
                avgMonthlySales: isTradeMode ? avgMonthlySales : undefined,
                highGrowth20: isTradeMode ? highGrowth20 : '',
                businessType: isTradeMode ? 'Trade' : 'Non-Trade'
            });
        }

        // Concentration & Net Exposure
        var hhiSum = 0;
        if (totalOutst > 0) {
            for (var h = 0; h < tableData.length; h++) {
                var share = (tableData[h].outstanding / totalOutst) * 100;
                hhiSum += share * share;
            }
        }
        var concentrationRisk = Math.round(hhiSum);
        var concentrationLabel = concentrationRisk > 2500 ? 'High' : (concentrationRisk >= 1500 ? 'Moderate' : 'Less');
        var netExposure = totalOutst - totalActiveSd;

        // Trend points
        var trendPoints = [];
        if (sysIds.length > 0) {
            var snapStartOut = sixMonths[0].year + '-' + pad2(sixMonths[0].month + 1) + '-01 00:00:00';
            var snapEndDay = new Date(sixMonths[5].year, sixMonths[5].month + 1, 0).getDate();
            var snapEndOut = sixMonths[5].year + '-' + pad2(sixMonths[5].month + 1) + '-' + pad2(snapEndDay) + ' 23:59:59';
            var outTrendAgg = {};
            var outChunks = [];
            var idsCopy = sysIds.slice();
            while (idsCopy.length) outChunks.push(idsCopy.splice(0, 2000));
            for (var oi = 0; oi < outChunks.length; oi++) {
                var gaOut = new GlideAggregate(tables.snapshot);
                gaOut.addQuery('customer', 'IN', outChunks[oi]);
                if (isTradeMode) {
                    gaOut.addQuery('snapshot_month', '>=', snapStartOut);
                    gaOut.addQuery('snapshot_month', '<=', snapEndOut);
                    gaOut.addAggregate('SUM', 'total_outstanding');
                    gaOut.groupBy('snapshot_month');
                } else {
                    gaOut.addQuery('created_on', '>=', snapStartOut);
                    gaOut.addQuery('created_on', '<=', snapEndOut);
                    gaOut.addAggregate('SUM', 'outstanding');
                    gaOut.groupBy('created_on');
                }
                gaOut.query();
                while (gaOut.next()) {
                    var ds = gaOut.getValue(isTradeMode ? 'snapshot_month' : 'created_on');
                    var ym = ds.substring(0, 7);
                    outTrendAgg[ym] = (outTrendAgg[ym] || 0) + (parseFloat(gaOut.getAggregate('SUM', isTradeMode ? 'total_outstanding' : 'outstanding')) || 0);
                }
            }
            sixMonths.forEach(function(m) {
                var ym = m.year + '-' + pad2(m.month + 1);
                trendPoints.push({
                    label: MONTH_NAMES[m.month] + ' ' + String(m.year).slice(-2),
                    value: outTrendAgg[ym] || 0
                });
            });
        }

        // Sales & Ageing
        var salesPoints = [];
        var ageingData = [];
        if (sysIds.length > 0) {
            var snapStart = snapStartOut;
            var snapEnd = snapEndOut;
            var snapAggMap = {};
            var snapChunks = [];
            var idsSnap = sysIds.slice();
            while (idsSnap.length) snapChunks.push(idsSnap.splice(0, 2000));
            for (var si = 0; si < snapChunks.length; si++) {
                var gaSnap = new GlideAggregate(tables.snapshot);
                gaSnap.addQuery('customer', 'IN', snapChunks[si]);
                if (isTradeMode) {
                    gaSnap.addQuery('snapshot_month', '>=', snapStart);
                    gaSnap.addQuery('snapshot_month', '<=', snapEnd);
                    gaSnap.addAggregate('SUM', 'bucket_0_30_days');
                    gaSnap.addAggregate('SUM', 'bucket_22_30_days');
                    gaSnap.addAggregate('SUM', 'bucket_31_45_days');
                    gaSnap.addAggregate('SUM', 'bucket_46_60_days');
                    gaSnap.addAggregate('SUM', 'bucket_61_75_days');
                    gaSnap.addAggregate('SUM', 'bucket_76_90_days');
                    gaSnap.addAggregate('SUM', 'bucket_91_120_days');
                    gaSnap.addAggregate('SUM', 'bucket_121_180_days');
                    gaSnap.addAggregate('SUM', 'bucket_181_365_days');
                    gaSnap.addAggregate('SUM', 'bucket_366_730_days');
                    gaSnap.addAggregate('SUM', 'bucket_730_above');
                    gaSnap.groupBy('snapshot_month');
                } else {
                    gaSnap.addQuery('created_on', '>=', snapStart);
                    gaSnap.addQuery('created_on', '<=', snapEnd);
                    gaSnap.addAggregate('SUM', 'ageing0_3');
                    gaSnap.addAggregate('SUM', 'ageing4_7');
                    gaSnap.addAggregate('SUM', 'ageing8_21');
                    gaSnap.addAggregate('SUM', 'ageing22_30');
                    gaSnap.addAggregate('SUM', 'ageing31_45');
                    gaSnap.addAggregate('SUM', 'ageing46_60');
                    gaSnap.addAggregate('SUM', 'ageing61_75');
                    gaSnap.addAggregate('SUM', 'ageing76_90');
                    gaSnap.addAggregate('SUM', 'ageing_gt90');
                    gaSnap.groupBy('created_on');
                }
                gaSnap.query();
                while (gaSnap.next()) {
                    var ds = gaSnap.getValue(isTradeMode ? 'snapshot_month' : 'created_on');
                    var ym = ds.substring(0, 7);
                    if (!snapAggMap[ym]) {
                        if (isTradeMode) {
                            snapAggMap[ym] = { b0_30:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0 };
                        } else {
                            snapAggMap[ym] = { b0_3:0, b4_7:0, b8_21:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, bGt90:0 };
                        }
                    }
                    if (isTradeMode) {
                        snapAggMap[ym].b0_30   += parseFloat(gaSnap.getAggregate('SUM','bucket_0_30_days')) || 0;
                        snapAggMap[ym].b22_30  += parseFloat(gaSnap.getAggregate('SUM','bucket_22_30_days')) || 0;
                        snapAggMap[ym].b31_45  += parseFloat(gaSnap.getAggregate('SUM','bucket_31_45_days')) || 0;
                        snapAggMap[ym].b46_60  += parseFloat(gaSnap.getAggregate('SUM','bucket_46_60_days')) || 0;
                        snapAggMap[ym].b61_75  += parseFloat(gaSnap.getAggregate('SUM','bucket_61_75_days')) || 0;
                        snapAggMap[ym].b76_90  += parseFloat(gaSnap.getAggregate('SUM','bucket_76_90_days')) || 0;
                        snapAggMap[ym].b91_120 += parseFloat(gaSnap.getAggregate('SUM','bucket_91_120_days')) || 0;
                        snapAggMap[ym].b121_180+= parseFloat(gaSnap.getAggregate('SUM','bucket_121_180_days')) || 0;
                        snapAggMap[ym].b181_365+= parseFloat(gaSnap.getAggregate('SUM','bucket_181_365_days')) || 0;
                        snapAggMap[ym].b366_730+= parseFloat(gaSnap.getAggregate('SUM','bucket_366_730_days')) || 0;
                        snapAggMap[ym].b730_above+= parseFloat(gaSnap.getAggregate('SUM','bucket_730_above')) || 0;
                    } else {
                        snapAggMap[ym].b0_3   += parseFloat(gaSnap.getAggregate('SUM','ageing0_3')) || 0;
                        snapAggMap[ym].b4_7   += parseFloat(gaSnap.getAggregate('SUM','ageing4_7')) || 0;
                        snapAggMap[ym].b8_21  += parseFloat(gaSnap.getAggregate('SUM','ageing8_21')) || 0;
                        snapAggMap[ym].b22_30 += parseFloat(gaSnap.getAggregate('SUM','ageing22_30')) || 0;
                        snapAggMap[ym].b31_45 += parseFloat(gaSnap.getAggregate('SUM','ageing31_45')) || 0;
                        snapAggMap[ym].b46_60 += parseFloat(gaSnap.getAggregate('SUM','ageing46_60')) || 0;
                        snapAggMap[ym].b61_75 += parseFloat(gaSnap.getAggregate('SUM','ageing61_75')) || 0;
                        snapAggMap[ym].b76_90 += parseFloat(gaSnap.getAggregate('SUM','ageing76_90')) || 0;
                        snapAggMap[ym].bGt90  += parseFloat(gaSnap.getAggregate('SUM','ageing_gt90')) || 0;
                    }
                }
            }

            sixMonths.forEach(function(m) {
                var ym = m.year + '-' + pad2(m.month + 1);
                var lbl = MONTH_NAMES[m.month] + ' ' + String(m.year).slice(-2);
                salesPoints.push({ label: lbl, value: salesTrendMap[ym] || 0, volume: volumeTrendMap[ym] || 0 });
                var s = snapAggMap[ym];
                if (isTradeMode) {
                    s = s || { b0_30:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0 };
                    ageingData.push({
                        label: lbl,
                        buckets: [
                            { label: '0-30 Days', value: s.b0_30 + s.b22_30 },
                            { label: '31-60 Days', value: s.b31_45 + s.b46_60 },
                            { label: '61-90 Days', value: s.b61_75 + s.b76_90 },
                            { label: '91-120 Days', value: s.b91_120 },
                            { label: '121-180 Days', value: s.b121_180 },
                            { label: '>180 Days', value: s.b181_365 + s.b366_730 + s.b730_above }
                        ]
                    });
                } else {
                    s = s || { b0_3:0, b4_7:0, b8_21:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, bGt90:0 };
                    ageingData.push({
                        label: lbl,
                        buckets: [
                            { label: '0-30 Days', value: s.b0_3 + s.b4_7 + s.b8_21 + s.b22_30 },
                            { label: '31-60 Days', value: s.b31_45 + s.b46_60 },
                            { label: '61-90 Days', value: s.b61_75 + s.b76_90 },
                            { label: '>90 Days', value: s.bGt90 }
                        ]
                    });
                }
            });
        }

        return {
            tableData: tableData,
            kpis: {
                limit: totalLimit,
                outstanding: totalOutst,
                available: totalLimit - totalOutst,
                utilPct: totalLimit > 0 ? Math.round((totalOutst / totalLimit) * 100) : 0,
                overdueExposure: totalOverdue,
                od90: totalOd90,
                grossExposure: totalGross,
                expiringCount: expCnt,
                pendingCount: pendingCnt,
                sendBackCount: sendBackCnt,
                rejectedCount: rejectCnt,
                concentrationRisk: concentrationRisk,
                concentrationLabel: concentrationLabel,
                netExposure: netExposure,
                osSalesRatioSum: tableData.reduce(function(s, r) { return s + (r.osSalesRatio || 0); }, 0)
            },
            trend: { metric: 'outstanding', points: trendPoints },
            salesTrend: { metric: 'sales', points: salesPoints },
            ageingTrend: { months: ageingData }
        };
    }

    // ======================= EXECUTION =======================
    var resultTrade = null, resultNT = null;

    if (isAll) {
        var unifiedLabel = inputFilters.segment || '';
        var tradeSegment = unifiedLabel;
        var ntSegment = NT_SEG_REVERSE[unifiedLabel] || unifiedLabel;

        resultTrade = processMode(true, tradeSegment);
        resultNT = processMode(false, ntSegment);

        data.tableData = resultTrade.tableData.concat(resultNT.tableData);
        var kT = resultTrade.kpis, kN = resultNT.kpis;
        data.kpis = {
            limit: kT.limit + kN.limit,
            outstanding: kT.outstanding + kN.outstanding,
            available: (kT.limit + kN.limit) - (kT.outstanding + kN.outstanding),
            utilPct: (kT.limit + kN.limit) > 0 ? Math.round(((kT.outstanding + kN.outstanding) / (kT.limit + kN.limit)) * 100) : 0,
            overdueExposure: kT.overdueExposure + kN.overdueExposure,
            od90: kT.od90 + kN.od90,
            grossExposure: kT.grossExposure + kN.grossExposure,
            expiringCount: kT.expiringCount + kN.expiringCount,
            pendingCount: kT.pendingCount + kN.pendingCount,
            sendBackCount: kT.sendBackCount + kN.sendBackCount,
            rejectedCount: kT.rejectedCount + kN.rejectedCount,
            concentrationRisk: 0,
            concentrationLabel: '—',
            netExposure: kT.netExposure + kN.netExposure,
            osSalesRatioSum: kT.osSalesRatioSum + kN.osSalesRatioSum
        };

        var tradeOpts = buildTradeFilterOptions();
        var ntOpts = buildNTFilterOptions();

        var unionZones = tradeOpts.zones.concat(ntOpts.zones)
            .filter(function(v,i,a){ return a.findIndex(function(t){ return t.value===v.value; })===i; })
            .sort(function(a,b){ return a.label.localeCompare(b.label); });
        var unionRegions = tradeOpts.regions.concat(ntOpts.regions)
            .filter(function(v,i,a){ return a.findIndex(function(t){ return t.value===v.value; })===i; })
            .sort(function(a,b){ return a.label.localeCompare(b.label); });
        var unionDepots = tradeOpts.depots.concat(ntOpts.depots)
            .filter(function(v,i,a){ return a.findIndex(function(t){ return t.value===v.value; })===i; })
            .sort(function(a,b){ return a.label.localeCompare(b.label); });

        var segmentMap = {};
        tradeOpts.segments.forEach(function(s) {
            if (!segmentMap[s.label]) segmentMap[s.label] = { value: s.label, label: s.label };
        });
        ntOpts.segments.forEach(function(s) {
            if (!segmentMap[s.label]) segmentMap[s.label] = { value: s.label, label: s.label };
        });
        var unionSegments = Object.keys(segmentMap).map(function(k) { return segmentMap[k]; })
            .sort(function(a,b){ return a.label.localeCompare(b.label); });

        data.filterOpts = {
            zones: unionZones,
            regions: unionRegions,
            depots: unionDepots,
            segments: unionSegments,
            periods: tradeOpts.periods
        };

        data.trend = { points: [] };
        data.salesTrend = { points: [] };
        data.ageingTrend = { months: [] };
    } else {
        var active = isTrade ? processMode(true) : processMode(false);
        data.tableData = active.tableData;
        data.kpis = active.kpis;
        data.trend = active.trend;
        data.salesTrend = active.salesTrend;
        data.ageingTrend = active.ageingTrend;
        data.filterOpts = isTrade ? buildTradeFilterOptions() : buildNTFilterOptions();
        data.filterOpts.periods = [
            { label: 'All Time (Latest)', value: 'latest' },
            { label: 'This Month', value: 'this_month' },
            { label: 'Last Month', value: 'last_month' },
            { label: 'This Year', value: 'this_year' },
            { label: 'Last Year', value: 'last_year' }
        ];
    }

    data.selectedZones = inputFilters.zones;
    data.selectedRegions = inputFilters.regions;
    data.business = business;
})();
